-- ----------------------------
-- Table structure for `star_snapshots`
-- ----------------------------
DROP TABLE IF EXISTS `star_snapshots`;
CREATE TABLE `star_snapshots` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `repository_id` bigint(20) unsigned NOT NULL,
  `snapshot_date` date NOT NULL,
  `stars_count` int(10) unsigned NOT NULL DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_star_snapshots_repository_date` (`repository_id`,`snapshot_date`),
  KEY `idx_star_snapshots_date` (`snapshot_date`),
  CONSTRAINT `fk_star_snapshots_repository` FOREIGN KEY (`repository_id`) REFERENCES `repositories` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3571 DEFAULT CHARSET=utf8mb4;

